const input = $input.first().json;

// Which path woke Radar?
const wakeType = input.wake_type || 'unknown';

// Nigeria is UTC+1 year-round
const nowUtc = new Date();
const lagosNow = new Date(nowUtc.getTime() + 60 * 60 * 1000);

const year = lagosNow.getUTCFullYear();
const month = lagosNow.getUTCMonth();
const day = lagosNow.getUTCDate();
const hour = lagosNow.getUTCHours();

// Radar's real scan times
const slots = [9, 12, 15, 18, 20, 23];

// Find the latest scheduled slot that should already have happened
let slotHour = null;

for (const slot of slots) {
  if (slot <= hour) {
    slotHour = slot;
  }
}

// Start with today's Lagos date
let slotDate = new Date(Date.UTC(year, month, day));

// If it's before 9AM, the most recent owed slot was
// yesterday at 11PM.
if (slotHour === null) {
  slotHour = 23;
  slotDate.setUTCDate(slotDate.getUTCDate() - 1);
}

const yyyy = slotDate.getUTCFullYear();
const mm = String(slotDate.getUTCMonth() + 1).padStart(2, '0');
const dd = String(slotDate.getUTCDate()).padStart(2, '0');
const hh = String(slotHour).padStart(2, '0');

const dateString = `${yyyy}-${mm}-${dd}`;

const intendedSlot =
  `${dateString}T${hh}:00:00+01:00`;

const nowLagos =
  `${String(lagosNow.getUTCFullYear())}-${String(
    lagosNow.getUTCMonth() + 1
  ).padStart(2, '0')}-${String(
    lagosNow.getUTCDate()
  ).padStart(2, '0')}T${String(
    lagosNow.getUTCHours()
  ).padStart(2, '0')}:${String(
    lagosNow.getUTCMinutes()
  ).padStart(2, '0')}:${String(
    lagosNow.getUTCSeconds()
  ).padStart(2, '0')}+01:00`;

return [
  {
    json: {
      wake_type: wakeType,
      now_lagos: nowLagos,
      intended_slot: intendedSlot,
      slot_label: `${hh}:00`,
    },
  },
];

const source = $json;

const now = new Date();

const FIRST_RUN_LOOKBACK_HOURS = 24;
const OVERLAP_HOURS = 2;
const MAX_CATCHUP_HOURS = 48;

let catchupStart;

if (source.last_success_at && Number.isFinite(Date.parse(source.last_success_at))) {
  const lastSuccess = new Date(source.last_success_at);

  catchupStart = new Date(
    lastSuccess.getTime() -
    OVERLAP_HOURS * 60 * 60 * 1000
  );
} else {
  catchupStart = new Date(
    now.getTime() -
    FIRST_RUN_LOOKBACK_HOURS * 60 * 60 * 1000
  );
}

const maxStart = new Date(
  now.getTime() -
  MAX_CATCHUP_HOURS * 60 * 60 * 1000
);

if (catchupStart < maxStart) {
  catchupStart = maxStart;
}

return {
  json: {
    ...source,
    catchup_start: catchupStart.toISOString(),
    catchup_end: now.toISOString(),
    is_first_scan: !source.last_success_at
  }
};

const source =
  $('Calculate Catch-up Window')
    .itemMatching(0)
    .json;

if (!source?.source_id) {
  throw new Error(
    'Could not resolve linked source context'
  );
}

const windowStart = new Date(
  source.catchup_start
).getTime();

const windowEnd = new Date(
  source.catchup_end
).getTime();

if (!Number.isFinite(windowStart)) {
  throw new Error(
    `Invalid catchup_start for ${source.source_id}`
  );
}

if (!Number.isFinite(windowEnd)) {
  throw new Error(
    `Invalid catchup_end for ${source.source_id}`
  );
}


// -------------------------
// URL NORMALIZATION
// -------------------------

function cleanUrl(rawUrl) {
  if (!rawUrl) return '';

  try {
    const url = new URL(rawUrl);

    const trackingParams = [
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_term',
      'utm_content',
      'ref',
      'source'
    ];

    for (const param of trackingParams) {
      url.searchParams.delete(param);
    }

    url.hash = '';

    return url.toString();
  } catch {
    return String(rawUrl);
  }
}


// -------------------------
// STABLE LOCAL HASH
// -------------------------

function stableHash64(input) {
  let h1 = 2166136261;
  let h2 = 2246822519;

  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);

    h1 ^= c;
    h1 = Math.imul(h1, 16777619);

    h2 ^= c;
    h2 = Math.imul(h2, 3266489917);
  }

  return (
    (h1 >>> 0)
      .toString(16)
      .padStart(8, '0') +

    (h2 >>> 0)
      .toString(16)
      .padStart(8, '0')
  );
}


// -------------------------
// NORMALIZE FEED ITEMS
// -------------------------

const inputItems = $input.all();
const output = [];
const seenUids = new Set();

for (let i = 0; i < inputItems.length; i++) {
  const entry = inputItems[i].json;

  const publishedRaw =
    entry.isoDate ||
    entry.pubDate ||
    entry.published ||
    entry.updated ||
    null;

  if (!publishedRaw) {
    continue;
  }

  const publishedTime =
    new Date(publishedRaw).getTime();

  if (!Number.isFinite(publishedTime)) {
    continue;
  }

  // Outside this source's catch-up window
  if (
    publishedTime < windowStart ||
    publishedTime > windowEnd
  ) {
    continue;
  }


  // -------------------------
  // TITLE
  // -------------------------

  const title = String(
    entry.title || ''
  )
    .replace(/\s+/g, ' ')
    .trim();

  if (!title) {
    continue;
  }


  // -------------------------
  // URL
  // -------------------------

  const originalUrl =
    entry.link ||
    entry.guid ||
    '';

  const canonicalUrl =
    cleanUrl(originalUrl);


  // -------------------------
  // EXTERNAL ID
  // -------------------------

  const externalId =
    entry.guid ||
    canonicalUrl ||
    title;


  // -------------------------
  // EXCERPT
  // -------------------------

  const excerpt = String(
    entry.contentSnippet ||
    entry.content ||
    entry.description ||
    entry.summary ||
    ''
  )
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1500);


  // -------------------------
  // HASHES
  // -------------------------

  const itemUid = stableHash64(
    `${source.source_id}|${externalId}`
  );

  const contentHash = stableHash64(
    [
      title.toLowerCase(),
      canonicalUrl,
      excerpt
    ].join('|')
  );


  // -------------------------
  // OUTPUT
  // -------------------------

  if (seenUids.has(itemUid)) continue;
  seenUids.add(itemUid);

  output.push({
    json: {
      item_uid: itemUid,

      source_id: source.source_id,
      source_name: source.name,
      category: source.category,

      external_id:
        String(externalId),

      title,

      url:
        String(originalUrl || ''),

      canonical_url:
        canonicalUrl,

      excerpt,

      published_at:
        new Date(
          publishedTime
        ).toISOString(),

      fetched_at:
        new Date().toISOString(),

      content_hash:
        contentHash,

      status:
        'new'
    },

    pairedItem: {
      item: i
    }
  });
}

// A fetch containing no relevant dated articles is still a successful fetch.
// Preserve one control item so the per-source loop can finish correctly.
if (output.length === 0) {
  return [{
    json: { _radar_no_recent_items: true, source_id: source.source_id },
    pairedItem: { item: 0 }
  }];
}
return output;

// Runs ONCE after the source's normalized items have been saved
// (or after the explicit no-recent-articles sentinel).
const records = $input.all().map(x => x.json);
const sourceIds = [...new Set(records.map(x => String(x.source_id || '').trim()).filter(Boolean))];
if (sourceIds.length !== 1) {
  throw new Error(`Expected exactly one source after saving; got: ${sourceIds.join(', ')}`);
}
const now = new Date().toISOString();
return [{
  json: {
    source_id: sourceIds[0],
    last_attempt_at: now,
    last_success_at: now,
    consecutive_failures: 0,
    next_retry_at: '',
    last_error: '',
    stored_items_this_batch: records.filter(x => x.item_uid).length
  },
  pairedItem: { item: 0 }
}];

const source =
  $('Calculate Catch-up Window')
    .itemMatching(0)
    .json;

if (!source?.source_id) {
  throw new Error(
    'Could not resolve linked source context'
  );
}


// -------------------------
// ERROR INPUT
// -------------------------

const input =
  $input.first()?.json || {};

const now =
  new Date();


// -------------------------
// FAILURE COUNT
// -------------------------

const previousFailures =
  Number(
    source.consecutive_failures || 0
  );

const consecutiveFailures =
  previousFailures + 1;


// -------------------------
// RETRY BACKOFF
// -------------------------

let retryMinutes;

if (consecutiveFailures === 1) {
  retryMinutes = 5;

} else if (consecutiveFailures === 2) {
  retryMinutes = 15;

} else if (consecutiveFailures === 3) {
  retryMinutes = 60;

} else {
  retryMinutes = 180;
}

const nextRetry =
  new Date(
    now.getTime() +
    retryMinutes * 60 * 1000
  );


// -------------------------
// ERROR MESSAGE
// -------------------------

let errorMessage =
  input.error?.message ||
  input.message ||
  input.error?.description ||
  input.error ||
  'Source fetch failed';

if (
  typeof errorMessage === 'object'
) {
  try {
    errorMessage =
      JSON.stringify(errorMessage);
  } catch {
    errorMessage =
      'Source fetch failed';
  }
}

errorMessage =
  String(errorMessage)
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);


// -------------------------
// OUTPUT
// -------------------------

return [
  {
    json: {
      source_id:
        source.source_id,

      enabled:
        source.enabled === true,

      last_attempt_at:
        now.toISOString(),

      // Do NOT change last_success_at
      // when a fetch fails.

      consecutive_failures:
        consecutiveFailures,

      next_retry_at:
        nextRetry.toISOString(),

      last_error:
        errorMessage,

      retry_minutes:
        retryMinutes
    },

    pairedItem: {
      item: 0
    }
  }
];

const slot = $('Determine Due Slot').first().json;
const old = $json || {};
const now = Date.now();
const staleAfter = 90 * 60 * 1000;
const minReclaim = 15 * 60 * 1000;
const started = Date.parse(old.started_at || '');
const completed = Date.parse(old.completed_at || '');
const status = String(old.status || '');
if (status === 'success') return null;
if (status === 'running' && Number.isFinite(started) && now - started < staleAfter) return null;
if (['partial_success','failed','deferred'].includes(status) && Number.isFinite(completed) && now - completed < minReclaim) return null;
const nonce = `${now}_${Math.random().toString(36).slice(2,12)}`;
return {json:{...slot,claim_token:nonce,recovery_reason:!status?'new_slot':`resume_${status}`,previous_run_id:old.run_id||''}};

const item = $json;

const title = String(item.title || '')
  .replace(/\s+/g, ' ')
  .trim();

const excerpt = String(item.excerpt || '')
  .replace(/\s+/g, ' ')
  .trim();

const url = String(
  item.canonical_url ||
  item.url ||
  ''
).trim();

const haystack =
  `${title} ${excerpt}`.toLowerCase();


// ----------------------------------
// DEFAULT
// ----------------------------------

let status = 'candidate';
let filterReason = '';


// ----------------------------------
// RULE 1:
// BROKEN / LOW-INFORMATION RECORD
// ----------------------------------

if (!title) {
  status = 'discarded';
  filterReason = 'missing_title';
}

else if (!url) {
  status = 'discarded';
  filterReason = 'missing_url';
}


// ----------------------------------
// RULE 2:
// RECRUITMENT / CAREER POSTS
// ----------------------------------

else if (
  /\b(we'?re hiring|we are hiring|hiring now|job openings?|open roles?|careers at|join our team)\b/i
    .test(haystack)
) {
  status = 'discarded';
  filterReason = 'recruitment';
}


// ----------------------------------
// RULE 3:
// EVENTS / WEBINAR PROMOTION
// ----------------------------------

else if (
  /\b(register now|webinar|conference agenda|event recap|meet us at|watch the webinar|join us for the webinar)\b/i
    .test(haystack)
) {
  status = 'discarded';
  filterReason = 'event_promotion';
}


// ----------------------------------
// RULE 4:
// ROUNDUPS / NEWSLETTER CONTENT
// ----------------------------------

else if (
  /\b(weekly roundup|monthly roundup|week in review|newsletter|weekly digest|monthly digest)\b/i
    .test(haystack)
) {
  status = 'discarded';
  filterReason = 'roundup_or_newsletter';
}


// ----------------------------------
// RULE 5:
// GENERIC "TOP X" SEO CONTENT
// ----------------------------------

else if (
  /\b(top \d+ (ai|crypto|web3|agent|agents|tools|tokens)|best \d+ (ai|crypto|web3|tools|tokens))\b/i
    .test(title)
) {
  status = 'discarded';
  filterReason = 'seo_listicle';
}


// ----------------------------------
// RULE 6:
// LOW-VALUE CRYPTO PRICE CONTENT
// ----------------------------------

else if (
  /\b(price prediction|price analysis|technical analysis|top gainers?|top losers?|buy signal|sell signal|token price prediction)\b/i
    .test(haystack)
) {
  status = 'discarded';
  filterReason = 'price_spam';
}


// ----------------------------------
// RULE 7:
// GIVEAWAY / CLAIM SPAM
// ----------------------------------

else if (
  /\b(giveaway|whitelist giveaway|claim your airdrop|presale now|buy presale)\b/i
    .test(haystack)
) {
  status = 'discarded';
  filterReason = 'promo_spam';
}


// ----------------------------------
// OUTPUT
// ----------------------------------

return {
  json: {
    ...item,

    status,

    filter_reason:
      filterReason,

    filtered_at:
      new Date().toISOString()
  }
};

const original = $json;
const knownAiSources = new Set(['openai_news', 'huggingface_blog']);
const item = {
  ...original,
  category: original.category || (knownAiSources.has(original.source_id) ? 'AI' : '')
};
if (!item.category) {
  throw new Error(`Missing event category for source ${item.source_id || 'unknown'}`);
}

// Discarded items stop here.
// They stay in radar_items for stats/debugging,
// but they do not become Radar events.
if (item.status !== 'candidate') {
  return [];
}

function normalizeTitle(title) {
  const stopWords = new Set([
    'a', 'an', 'the',
    'and', 'or', 'but',
    'to', 'of', 'in', 'on',
    'for', 'with', 'from',
    'at', 'by', 'as',
    'is', 'are', 'was', 'were',
    'be', 'been', 'being',
    'new', 'latest',
    'announces', 'announced',
    'launches', 'launched',
    'releases', 'released',
    'introduces', 'introduced'
  ]);

  return String(title || '')
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(word =>
      word.length > 2 &&
      !stopWords.has(word)
    )
    .sort()
    .join(' ');
}

function stableHash64(input) {
  let h1 = 2166136261;
  let h2 = 2246822519;

  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);

    h1 ^= c;
    h1 = Math.imul(h1, 16777619);

    h2 ^= c;
    h2 = Math.imul(h2, 3266489917);
  }

  return (
    (h1 >>> 0).toString(16).padStart(8, '0') +
    (h2 >>> 0).toString(16).padStart(8, '0')
  );
}

const fingerprint =
  normalizeTitle(item.title);

const eventUid =
  stableHash64(
    `${item.category}|${fingerprint}`
  );

return {
  json: {
    ...item,

    event_uid: eventUid,

    title_fingerprint:
      fingerprint,

    event_first_seen_at:
      new Date().toISOString()
  }
};

const candidate =
  $('Prepare Event Candidate')
    .itemMatching(0)
    .json;

const existing = $json;

return {
  json: {
    item_uid: candidate.item_uid,

    event_uid: existing.event_uid,

    last_seen_at:
      new Date().toISOString(),

    source_count:
      Number(existing.source_count || 1) + 1
  }
};

// Live comparison only. Temporary test-mode forcing has been removed.
const candidate = $('Is New Event?').itemMatching(0).json;
if (!candidate?.event_uid) { throw new Error('Could not resolve current event candidate'); }
const recentEvents = $input.all().map(item => item.json).filter(event => event?.event_uid);

// NORMAL FUZZY MATCHING
// ------------------------------------

const RECENT_WINDOW_HOURS = 48;

function getTokens(text) {
  const stopWords = new Set([
    'the', 'and', 'for', 'with',
    'from', 'that', 'this', 'into',
    'about', 'new', 'launch',
    'launches', 'launched',
    'release', 'releases', 'released',
    'announce', 'announces', 'announced',
    'introduce', 'introduces', 'introduced'
  ]);

  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .split(' ')
      .filter(word =>
        word.length > 2 &&
        !stopWords.has(word)
      )
  );
}

function compareTitles(aText, bText) {
  const a = getTokens(aText);
  const b = getTokens(bText);

  if (!a.size || !b.size) {
    return {
      shared: 0,
      jaccard: 0,
      overlap: 0,
      score: 0
    };
  }

  let shared = 0;

  for (const token of a) {
    if (b.has(token)) shared++;
  }

  const unionSize = a.size + b.size - shared;
  const minSize = Math.min(a.size, b.size);

  const jaccard = shared / unionSize;
  const overlap = shared / minSize;

  return {
    shared,
    jaccard,
    overlap,
    score: (jaccard * 0.55) + (overlap * 0.45)
  };
}

const candidateText =
  candidate.title_fingerprint ||
  candidate.title ||
  '';

const candidateUrl =
  candidate.canonical_url ||
  candidate.url ||
  '';

const now = Date.now();

let bestMatch = null;

for (const event of recentEvents) {

  if (
    candidate.category &&
    event.category &&
    candidate.category !== event.category
  ) {
    continue;
  }

  const eventTime = new Date(
    event.last_seen_at ||
    event.first_seen_at ||
    0
  ).getTime();

  if (!Number.isFinite(eventTime)) {
    continue;
  }

  const ageHours =
    (now - eventTime) / 3600000;

  if (
    ageHours < 0 ||
    ageHours > RECENT_WINDOW_HOURS
  ) {
    continue;
  }

  const eventUrl =
    event.primary_source_url || '';

  if (
    candidateUrl &&
    eventUrl &&
    candidateUrl === eventUrl
  ) {
    bestMatch = {
      event,
      similarity: 1,
      shared_tokens: 999,
      match_reason: 'same_url'
    };

    break;
  }

  const eventText =
    event.title_fingerprint ||
    event.canonical_title ||
    '';

  const comparison = compareTitles(
    candidateText,
    eventText
  );

  const qualifies =
    comparison.shared >= 3 &&
    (
      comparison.jaccard >= 0.50 ||
      comparison.overlap >= 0.70
    );

  if (!qualifies) continue;

  if (
    !bestMatch ||
    comparison.score > bestMatch.similarity
  ) {
    bestMatch = {
      event,
      similarity: comparison.score,
      shared_tokens: comparison.shared,
      match_reason: 'title_similarity'
    };
  }
}

// ------------------------------------
// FINAL OUTPUT
// ------------------------------------

if (bestMatch) {
  return [{
    json: {
      ...candidate,

      fuzzy_match_found: true,

      matched_event_uid:
        bestMatch.event.event_uid,

      matched_event_title:
        bestMatch.event.canonical_title || '',

      matched_event_source_count:
        Number(bestMatch.event.source_count || 1),

      fuzzy_similarity:
        Number(bestMatch.similarity.toFixed(4)),

      shared_tokens:
        bestMatch.shared_tokens,

      match_reason:
        bestMatch.match_reason
    }
  }];
}

return [{
  json: {
    ...candidate,

    fuzzy_match_found: false,

    matched_event_uid: '',
    matched_event_title: '',
    matched_event_source_count: 0,

    fuzzy_similarity: 0,
    shared_tokens: 0,
    match_reason: 'none'
  }
}];

const item = $json;

if (!item.matched_event_uid) {
  throw new Error(
    'Fuzzy match was true but matched_event_uid is missing'
  );
}

return {
  json: {
    item_uid: item.item_uid,

    event_uid: item.matched_event_uid,

    last_seen_at:
      new Date().toISOString(),

    source_count:
      Number(
        item.matched_event_source_count || 1
      ) + 1
  }
};

const completedSources = $input.all();

return [
  {
    json: {
      stage: 'event_processing',
      sources_completed: completedSources.length,
      started_at: new Date().toISOString()
    }
  }
];

const inputItems = $input.all();

const pending = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i].json;

  // Only process genuine candidates.
  if (item.status !== 'candidate') {
    continue;
  }

  // Already linked to an event?
  if (String(item.event_uid ?? '').trim()) {
    continue;
  }

  // A candidate must have a persistent item ID.
  if (!item.item_uid) {
    throw new Error(
      'Pending candidate is missing item_uid'
    );
  }

  pending.push({
    item,
    inputIndex: i
  });
}

// No unprocessed candidates.
// Return one control item so the workflow
// can continue to its completion path.
if (pending.length === 0) {
  return [{
    json: {
      has_pending_items: false,
      pending_count: 0,
      stage: 'no_pending_events'
    }
  }];
}

// Return only candidates awaiting event processing.
return pending.map(({ item, inputIndex }) => ({
  json: {
    ...item,
    has_pending_items: true,
    pending_count: pending.length
  },
  pairedItem: {
    item: inputIndex
  }
}));

const items = $input.all();

// Keep only valid linked articles.
const articles = items
  .map(item => item.json)
  .filter(item =>
    item.item_uid &&
    item.event_uid
  );

// A successfully linked article should exist.
if (articles.length === 0) {
  throw new Error(
    'No linked articles found for event source counting'
  );
}

// Ensure every returned article belongs
// to the same canonical event.
const eventIds = new Set(
  articles.map(item => String(item.event_uid).trim())
);

if (eventIds.size !== 1) {
  throw new Error(
    'Source counting received articles from multiple events'
  );
}

// Ensure no article is missing its source.
if (articles.some(item => !String(item.source_id || '').trim())) {
  throw new Error(
    'A linked article is missing source_id'
  );
}

// Count distinct reporting sources,
// not articles or processing attempts.
const uniqueSources = new Set(
  articles.map(item =>
    String(item.source_id).trim()
  )
);

const eventUid = [...eventIds][0];

return [
  {
    json: {
      event_uid: eventUid,
      source_count: uniqueSources.size,
      linked_item_count: articles.length,
      counted_at: new Date().toISOString()
    }
  }
];

const source = $input.first().json;

if (!source.source_id) {
  throw new Error('Skipped source has no source_id');
}

return [{
