for (const row of rows) {
  const id = String(row.source_id || '').trim();
  const state = String(row.source_outcome || '').trim();
  if (!id || !allowed.has(state)) throw new Error('Source loop did not return a valid (source_id, source_outcome) item');
  if (bySource.has(id)) throw new Error(`Duplicate source outcome: ${id}`);
  bySource.set(id,{state,error:String(row.last_error||'')});
}
const expected = $('Load Enabled Sources').all().filter(x=>x.json?.source_id).length;
if (!expected || expected !== bySource.size) throw new Error(`Source outcome mismatch: expected ${expected}, received ${bySource.size}`);
