const failed=vals.filter(x=>x.state==='failed').length;
const skipped=vals.filter(x=>x.state==='skipped').length;
const errors=[...bySource].filter(([id,v])=>v.state==='failed').map(([id,v])=>`${id}: ${v.error||'fetch failed'}`);
return [{json:{sources_attempted:succeeded+failed,sources_succeeded:succeeded,sources_failed:failed,sources_skipped:skipped,source_error_summary:errors.join(' | ').slice(0,1000),outcomes:[...bySource].map(([source_id,v])=>({source_id,source_outcome:v.state})),stage:'sources_counted'}}];

