// RADAR RELEVANCE v2.2 — conservative, title-grounded security qualification.
// Gate FIRST, rank SECOND. No funding or famous-company bonuses.
// Event rows currently contain titles/URLs, not the full source excerpt.
// Practical implications below are explicitly conditional, not claims of verified capabilities.
const cfg = $('Radar Runtime Config').first().json;
const now = Date.now();
const cutoff = now - 48 * 60 * 60 * 1000;
const events = [];
const rejected = [];
let considered = 0;
const clean = x => String(x ?? '').replace(/\s+/g, ' ').trim();
const has = (t, r) => r.test(t);

function qualify(title, category) {
 const t = title.toLowerCase();
 // High-priority exclusion: real news isn't automatically a useful builder signal.
 if (/\b(raises?|raised|funding|fundraise|fundraising|valuation|valued at|investment round|series [a-f]|acquisition|acquires?|merger|buyout)\b|\bworth\s*\$|\$\s*\d+(?:\.\d+)?\s*(?:b|m|billion|million)\s+(?:deal|funding|investment)/i.test(t)) return {reject:'funding_or_valuation'};
 if (/\b(in talks|reportedly.*deal|compute deal|infrastructure deal|partnership talks|rumou?red deal|reportedly in discussions)\b/i.test(t)) return {reject:'speculative_deal'};
 if (/\b(price prediction|technical analysis|top gainers?|top losers?|sponsored|newsletter|roundup|webinar|giveaway)\b/i.test(t)) return {reject:'low_value_content'};
 const change = /\b(launch(?:es|ed|ing)?|release(?:s|d)?|ship(?:s|ped)?|introduc(?:e|es|ed|ing)|unveil(?:s|ed)?|debut(?:s|ed)?|roll(?:s|ed)? out|announc(?:e|es|ed)|add(?:s|ed)?|new|updat(?:e|es|ed)|now available|available|open.source|open.weight|support(?:s|ed)?|cuts?|reduces?|drops?|lower(?:s|ed)?|increas(?:e|es|ed)|deprecat(?:e|es|ed)|fix(?:es|ed)?|patch(?:es|ed)?|expands?|integrat(?:e|es|ed))\b/i;
 const model = /\b(models?|llms?|open[ -]source|open[ -]weight|model weights|embeddings?|reasoning models?|language models?|vision models?)\b/i;
 const open = /\b(open[ -]source|open[ -]weight|open models?|model weights|runs? (?:locally|on (?:a )?pc)|on pcs|self[ -]host(?:ed|ing)?)\b/i;
 const pricing = /\b(pricing|price cuts?|costs?|cheaper|free tier|per[- ]token|input tokens?|output tokens?|rate cuts?|discount(?:s|ed)?)\b/i;
 const pricingChange = /\b(cuts?|reduces?|drops?|lowers?|slashes?|new pricing|price cuts?|cheaper|increas(?:e|es|ed)|changes?|updated|introduces?)\b/i;
 const api = /\b(apis?|sdks?|endpoints?|rate limits?|context windows?|tool calling|function calling|structured outputs?|mcp|developer platforms?|batch api|inference api)\b/i;
 const dev = /\b(developer tools?|dev tools?|coding agents?|coding assistants?|claude code|codex|cursor|openrouter|mcp servers?|orchestrat(?:ion|ors?)|agent frameworks?|torchneuron|code editors?|cli tools?|coding tools?)\b/i;
 const agent = /\b(agents?|agentic|autonomous workflows?|multi[ -]agent|agent workflows?)\b/i;
 // v2.2 security: demand an AI builder context AND evidence of an actual incident or concrete patch.
 // An opinion about hypothetical attacks does not qualify. Title-only -> cautious language.
 const aiBuilder = /\b(ai|llms?|agents?|coding (?:tools?|assistants?|agents?)|developer tools?|dev tools?|api(?:s| keys?| tokens?| accounts?)?|open[ -]?code|opencode|claude code|cursor|codex|mcp|openai|anthropic|gemini|deepseek|openrouter|model providers?)\b/i;
 const confirmedAttack = /\b(?:hackers?|attackers?|cybercriminals?)\s+(?:hit|attack(?:ed)?|breach(?:ed)?|compromis(?:ed|e)|hijack(?:ed)?|stole|steal|expos(?:ed|e)|leak(?:ed)?|exploited?)\b|\b(?:hacked|breached|compromised|hijacked|exploited|stolen|leaked)\b|\b(?:data|security) breach\b/i;
 const concreteImpact = /\b(?:api (?:keys?|tokens?|accounts?|credentials?|billing|spending|charges?|usage)|access tokens?|credentials?|accounts?|users?|developer accounts?|unauthori[sz]ed|charges?|spending|bill(?:ing)?|funds?|expos(?:ed|e)(?:\s+keys?)?|leak(?:ed)?|stol(?:en|e)|disrupt(?:ion|ed)?|service outage|customer data)\b/i;
 const patchedFlaw = /\b(?:patch(?:es|ed)?|fix(?:es|ed)?|resolv(?:es|ed)?|closes?)\b/i.test(t)
   && /\b(?:critical (?:security )?(?:flaw|bug|vulnerability)|vulnerabilit(?:y|ies)|zero[ -]day|security flaw|remote code execution|rce|credential leak|prompt injection flaw)\b/i.test(t);
 const securityIncident = has(t,aiBuilder) && ((has(t,confirmedAttack) && has(t,concreteImpact)) || patchedFlaw);
 const spendOrKeys = /\b(?:unauthori[sz]ed|(?:running|ran|racked?) up charges?|api (?:keys?|tokens?|accounts?|billing|spending|charges?|usage)|credentials?)\b/i.test(t);
 const market = /\b(bitcoin|btc|ethereum|eth|solana|stablecoin|crypto|digital assets?)\b/i;
 const materialMarket = /\b(etf inflows?|etf outflows?|record liquidations?|liquidations? (?:surge|spike)|regulator (?:approves?|bans?)|sec (?:approves?|rejects?)|major (?:hack|breach)|stablecoin depeg|depegs?)\b/i;
 const aiCrypto = /\b(ai|agent|model)\b.*\b(on[ -]chain|blockchain|crypto|web3)\b|\b(on[ -]chain|blockchain|crypto|web3)\b.*\b(ai|agent|model)\b/i;
 const changed = has(t,change);
 // A quoted opinion or generic industry warning is not an actionable incident.
 if (/\b(says?|argues?|predicts?|opinion|experts? (?:say|raving)|policy chief|won.t be an easy solution|like insider threats)\b/i.test(t) && !(securityIncident || (has(t,model) && changed && /\b(launch|releas|unveil|debut|introduc|shipp)\b/i.test(t)))) return {reject:'commentary_without_actionable_change'};
 let kind='', reason='', why='', score=0;
 if (securityIncident) {
   kind='agent_security'; score=85; reason='AI developer security incident or mitigation';
   why=spendOrKeys
     ? 'Reported AI tool security issue could expose credentials or cause unauthorized API spending; verify affected service, rotate exposed keys and review usage.'
     : 'Reported security issue may affect AI development workflows; verify the affected service or versions and mitigation steps.';
 } else if (has(t,pricing) && has(t,pricingChange) && (has(t,api)||has(t,model)|| /\b(inference|tokens?|claude|gpt|gemini|deepseek|glm)\b/i.test(t))) {
   kind='api_pricing'; score=88; reason='API or inference pricing change';
   why='Could change the cost of running AI workflows; compare new prices with your actual token usage.';
 } else if (has(t,model) && changed) {
   kind=has(t,open)?'open_model':'model_release'; score=has(t,open)?86:82;
   reason=has(t,open)?'Open model / capability release':'Model or capability release';
   why=has(t,open)
     ? (/(?:on pcs?|locally|on (?:a )?pc)/i.test(t) ? 'Could expand options for agent workflows on PCs; verify weights, hardware requirements and benchmarks.' : 'Could offer self-hosted inference options; verify available weights, licensing, hardware needs and benchmarks.')
     : 'Worth evaluating for coding or reasoning quality, latency, API availability and cost.';
 } else if (has(t,api) && changed) {
   kind='api_change'; score=81; reason='API / integration change';
   why='May change how your AI workflows integrate with models; check availability, compatibility and migration needs.';
 } else if (has(t,dev) && changed) {
   kind='developer_tool'; score=79; reason='New developer or coding-agent tool';
   why='Could improve how you build or deploy AI systems; check integrations, supported environments and real-world performance.';
 } else if (has(t,agent) && changed) {
   kind='agent_capability'; score=78; reason='New agent capability';
   why='Could expand practical automation options; test permissions, reliability and integrations before adopting it.';

 } else if (has(t,market) && has(t,materialMarket)) {
   kind='crypto_market'; score=76; reason='Significant crypto market event';
   why='May affect crypto liquidity or risk; verify the reported figures and the broader market context.';
 } else if (has(t,aiCrypto) && changed) {
   kind='ai_crypto'; score=76; reason='AI × crypto product or infrastructure';
   why='Potential on-chain agent or AI infrastructure development; check the working product, adoption and technical constraints.';
 } else {
   return {reject:'no_concrete_builder_relevance'};
 }
 if (has(t,open) && kind==='open_model') score+=3;
 return {kind,reason,why,score};
}

for (const item of $input.all()) {
 const e = item.json || {};
 if (!e.event_uid || !e.canonical_title || e.delivery_status !== 'not_selected') continue;
 const seen = Date.parse(e.last_seen_at || e.first_seen_at || '');
 if (!Number.isFinite(seen) || seen < cutoff || seen > now + 5*60000) continue;
 const title=clean(e.canonical_title);
 const url=clean(e.primary_source_url);
 if (!/^https?:\/\//i.test(url) || /example\.com|radar-test|internal test/i.test(`${url} ${title}`)) continue;
 considered++;
 const q=qualify(title,clean(e.category));
 if (q.reject) {
   if (rejected.length < 60) rejected.push({event_uid:String(e.event_uid),title,reason:q.reject});
   continue;
 }
 const sources=Math.max(1,Number(e.source_count)||1);
 const ageHours=(now-seen)/3600000;
 const score=Math.min(100,q.score + Math.min(6,Math.max(0,sources-1)*3) + (ageHours<=24?4:0));
 events.push({event_uid:String(e.event_uid),title,url,category:clean(e.category)||'AI',source_count:sources,score,reason:q.reason,why_it_matters:q.why,relevance_type:q.kind,seen_at:e.last_seen_at||e.first_seen_at});
}
events.sort((a,b)=>b.score-a.score || String(b.seen_at).localeCompare(String(a.seen_at)));
return [{json:{events:events.slice(0,35),considered_count:considered,filtered_count:considered-events.length,rejected_events:rejected,config:{telegram_enabled:cfg.telegram_enabled,telegram_chat_id:cfg.telegram_chat_id,openai_enabled:cfg.openai_enabled,openai_model:cfg.openai_model,min_relevance_score:cfg.min_relevance_score,max_digest_items:cfg.max_digest_items}}}];

// RADAR RELEVANCE v2.2 — preserve familiar Telegram layout, upgrade reasoning.
const batch=$('Prepare Relevance Batch').first().json;
const cfg=batch.config;
const base=batch.events||[];
const incoming=$input.first()?.json||{};
let overrides=[];
try {
 const raw=incoming.choices?.[0]?.message?.content;
 const parsed=raw?JSON.parse(raw):{};
 if(Array.isArray(parsed.scores))overrides=parsed.scores;
} catch {}
const scoreMap=new Map(overrides.filter(x=>typeof x.event_uid==='string' && Number.isFinite(Number(x.score))).map(x=>[x.event_uid,x]));
// AI may adjust ranking modestly but cannot resurrect an event rejected by the deterministic gate.
// Use title-grounded practical implications even if optional AI output gives a generic rationale.
const ranked=base.map(e=>{
 const ai=scoreMap.get(e.event_uid);
 const proposed=ai?Math.max(0,Math.min(100,Math.round(Number(ai.score)))):e.score;
 const score=ai?Math.max(0,Math.min(100,Math.max(e.score-15,Math.min(e.score+15,proposed)))):e.score;
 return {...e,score};
}).sort((a,b)=>b.score-a.score || String(b.seen_at).localeCompare(String(a.seen_at)));
const max=Math.max(1,Math.min(7,Number(cfg.max_digest_items||7)));
const selected=ranked.filter(e=>e.score>=Number(cfg.min_relevance_score||40)).slice(0,max);
const slot=$('Determine Due Slot').first().json.intended_slot;
const lines=[`ZINITOH RADAR | ${slot.slice(0,16).replace('T',' ')} WAT`,`Signals: ${selected.length} | Sources are linked for independent verification`,''];
selected.forEach((e,i)=>{
 lines.push(`${i+1}. [${e.category}] ${e.title.slice(0,180)}`);
 lines.push(`   Why it matters: ${e.why_it_matters} | ${e.source_count} reporting source(s)`);
 lines.push(`   ${e.url}`,'');
});
lines.push('Automated prioritization; verify primary sources before acting.');
const text=lines.join('\n').slice(0,3900);
const shouldQueue=cfg.telegram_enabled === true && !!cfg.telegram_chat_id && cfg.telegram_chat_id !== 'CONFIGURE_CHAT_ID' && selected.length>0;
return [{json:{should_queue:shouldQueue,digest_uid:`radar_${slot.replace(/[^0-9]/g,'')}`,run_slot:slot,digest_text:text,selected_events:selected,selected_count:selected.length,scored_count:ranked.length,considered_count:batch.considered_count??ranked.length,filtered_count:batch.filtered_count??0,rejected_events:batch.rejected_events||[],ranking_engine:scoreMap.size?'openai_with_local_gate':'local_relevance_gate_v2_2'}}];

// Persist actionable ranking rationale (no generic participant labels).
const digest=$('Rank And Compose Radar Digest').first().json;
return (digest.selected_events||[]).map(e=>({json:{event_uid:e.event_uid,delivery_status:'queued',radar_reason:e.reason,why_it_matters:e.why_it_matters||'',what_happened:e.title}}));

